    def batch_section() -> None:
        files = st.file_uploader("Upload file(s)", type=["csv", "txt", "tsv", "xlsx"], accept_multiple_files=True,
                                 label_visibility="collapsed")
        if not files:
            return

        parts = []
        for uf in files:
            part = load_any_dataframe(uf)
            part["_Source_File"] = uf.name
            parts.append(part)
        raw_df = pd.concat(parts, ignore_index=True)

        text_cols = get_valid_text_columns(raw_df)
        auto_text = detect_text_column(raw_df)
        c1, c2, c3 = st.columns([2, 2, 1.3])
        with c1:
            text_col = st.selectbox("Text column", text_cols,
                                    index=text_cols.index(auto_text) if auto_text in text_cols else 0)
        with c2:
            model_key = st.selectbox("Model", FOUR_MODELS, format_func=lambda k: MODEL_CATALOG[k]["short"])
        with c3:
            st.write("")
            st.write("")
            run = st.button("Run Prediction", type="primary", width="stretch")

        label_col = detect_label_column(raw_df)
        has_labels = label_col in raw_df.columns and label_col != text_col
        batch_sig = f"{[f.name for f in files]}|{len(raw_df)}|{text_col}|{model_key}"

        if run:
            clean_texts = raw_df[text_col].astype(str).apply(clean_social_text).tolist()
            bar = st.progress(0.0)
            t0 = time.time()
            preds, confs, _ = run_model_inference(
                model_key, clean_texts, progress_callback=lambda f, d, n: bar.progress(min(float(f), 1.0))
            )
            bar.empty()
            out = pd.DataFrame({
                "ID": raw_df["ID"].values if "ID" in raw_df.columns else np.arange(1, len(raw_df) + 1),
                "Text": raw_df[text_col].astype(str).values,
                "Predicted Label": preds,
                "Confidence": confs,
            })
            if has_labels:
                out["True Label"] = raw_df[label_col].apply(normalize_stance_label).values
            st.session_state["batch_out"] = (out, model_key, time.time() - t0, batch_sig)

        saved = st.session_state.get("batch_out")
        if not saved or saved[3] != batch_sig:
            return
        out, used_model, secs, _ = saved
        counts = out["Predicted Label"].value_counts()

        extra = ""
        if "True Label" in out.columns:
            acc = accuracy_score(out["True Label"], out["Predicted Label"])
            mf1 = f1_score(out["True Label"], out["Predicted Label"], average="macro", zero_division=0)
            extra = f'<div class="stat-summary-box"><div class="lbl">Accuracy / Macro F1</div><div class="val">{acc*100:.1f}% &middot; {mf1:.3f}</div></div>'
        else:
            extra = f'<div class="stat-summary-box"><div class="lbl">Rows &middot; Time</div><div class="val">{len(out)} &middot; {secs:.1f}s</div></div>'

        html_block(
            f"""
            <div class="stat-summary-row">
                <div class="stat-summary-box"><div class="lbl">🟢 Favor</div><div class="val">{int(counts.get('FAVOR', 0))}</div></div>
                <div class="stat-summary-box"><div class="lbl">🔴 Against</div><div class="val">{int(counts.get('AGAINST', 0))}</div></div>
                <div class="stat-summary-box"><div class="lbl">⚪ None</div><div class="val">{int(counts.get('NONE', 0))}</div></div>
                {extra}
            </div>
            """
        )

        d1, d2 = st.columns(2)
        with d1:
            st.download_button("Download submission CSV (ID, Predicted Label)",
                               out[["ID", "Predicted Label"]].to_csv(index=False).encode("utf-8-sig"),
                               "submission_predictions.csv", "text/csv", type="primary", width="stretch")
        with d2:
            st.download_button("Download detailed CSV",
                               out.to_csv(index=False).encode("utf-8-sig"),
                               "detailed_stance_predictions.csv", "text/csv", width="stretch")

        body = ""
        for _, r in out.head(100).iterrows():
            lab = r["Predicted Label"]
            body += (
                f"<tr><td>{esc(r['ID'])}</td><td>{esc(r['Text'])}</td>"
                f'<td><span class="status-badge {lab.lower()}" style="margin:0">{STANCE_ICON[lab]} {lab}</span></td>'
                f"<td>{float(r['Confidence'])*100:.1f}%</td></tr>"
            )
        html_block(
            f"""
            <div class="table-wrapper"><table class="app-table">
            <thead><tr><th>ID</th><th>Comment</th><th>Stance</th><th>Confidence</th></tr></thead>
            <tbody>{body}</tbody></table></div>
            """
        )


