    def performance_chart(rows: list):
        names = [MODEL_CATALOG[r[0]]["short"].replace("AI4Bharat ", "").replace("Multilingual BERT", "mBERT").replace("Google ", "") for r in rows]
        metrics = [("Accuracy", 1, "#FFFFFF"), ("Macro F1", 2, "#38BDF8"), ("Weighted F1", 3, "#2DD4BF")]
        x = np.arange(len(rows))
        w = 0.26
        fig, ax = plt.subplots(figsize=(10, 3.8))
        fig.patch.set_facecolor('#1C1F24')
        ax.set_facecolor('#1C1F24')
        for i, (label, idx, color) in enumerate(metrics):
            vals = [r[idx] for r in rows]
            bars = ax.bar(x + (i - 1) * w, vals, w, label=label, color=color, edgecolor='#0B0D12', linewidth=0.5)
            for b in bars:
                ax.text(b.get_x() + b.get_width() / 2, b.get_height() + 0.015, f"{b.get_height():.2f}",
                        ha="center", va="bottom", fontsize=8.5, color="#FFFFFF", fontweight="bold")
        ax.set_xticks(x)
        ax.set_xticklabels(names, color="#FFFFFF", fontsize=10.5, fontweight="600")
        ax.set_ylim(0, 1.05)
        ax.tick_params(axis="y", colors="#9CA3AF", labelsize=8.5)
        for s in ax.spines.values():
            s.set_visible(False)
        ax.grid(axis="y", color="#FFFFFF", alpha=0.08)
        ax.set_axisbelow(True)
        leg = ax.legend(frameon=False, loc="upper right", ncol=3, fontsize=9.5)
        for t in leg.get_texts():
            t.set_color("#FFFFFF")
        plt.tight_layout()
        return fig


